const ASSETS = {"/404": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Page not found · PhraseLane</title><meta name=\"description\" content=\"This page could not be found.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Page not found\"><meta property=\"og:description\" content=\"This page could not be found.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/404\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/404\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"><meta name=\"robots\" content=\"noindex\"></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><span class=\"eyebrow\">404 / A small detour</span><h1>Lost in navigation?</h1><p>The page could not be found.</p><a class=\"button\" href=\"/\">Back to the workspace ↗</a></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/account": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Your account · PhraseLane</title><meta name=\"description\" content=\"Manage your PhraseLane account and subscription access.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Your account\"><meta property=\"og:description\" content=\"Manage your PhraseLane account and subscription access.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/account\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/account\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"><meta name=\"robots\" content=\"noindex\"><script src=\"/app.js\" defer></script></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"wrap\"><div class=\"accountbox\"><span class=\"eyebrow\">Your workspace access</span><h1>Your account.</h1><p id=\"accountState\">Checking account…</p><p id=\"billingState\" class=\"notice\">Checking subscription availability…</p><div id=\"status\" class=\"status\" role=\"status\" aria-live=\"polite\"></div><section class=\"card\" data-unsigned><h2>Start an account</h2><p>Your account uses a private recovery key instead of a password. Save it in your password manager: anyone with it can access the account.</p><button id=\"createAccount\" class=\"button\">Create free account</button><h3>Already have a key?</h3><form id=\"loginForm\"><label for=\"loginKey\">Account recovery key</label><input id=\"loginKey\" class=\"field\" type=\"password\" autocomplete=\"off\" placeholder=\"PL-…\" required><button class=\"button secondary\" type=\"submit\">Restore account</button></form></section><section id=\"keyPanel\" class=\"card\" hidden><h2>Save this key now</h2><p>It is shown only once. We cannot recover it for you. Never send it in a translation or share it publicly.</p><p id=\"recoveryKey\" class=\"key\"></p><button id=\"copyKey\" class=\"button secondary\">Copy private key</button></section><section class=\"card\" data-signed hidden><h2>Subscription</h2><p>Pro: $9 USD per month when available. Renews monthly until cancelled. 50,000 input characters per calendar month, with daily and per-request limits.</p><label class=\"check\"><input id=\"savedKey\" type=\"checkbox\">I have saved my private account key.</label><label class=\"check\"><input id=\"acceptTerms\" type=\"checkbox\">I have read the <a href=\"/terms\">terms</a> and <a href=\"/privacy\">privacy policy</a>.</label><div class=\"row\"><button id=\"subscribe\" class=\"button\" disabled>Continue to secure checkout</button><button id=\"portal\" class=\"button secondary\" hidden>Manage billing / cancel</button><button id=\"logout\" class=\"iconbtn\">Sign out</button></div></section></div></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/app.js": {"content": "'use strict';\nconst $=s=>document.querySelector(s);let config,account={signedIn:false,plan:'free'},seq=0,recognition,recognizing=false;const cache=new Map();\nconst status=(msg,error=false)=>{const e=$('#status');if(e){e.textContent=msg;e.classList.toggle('error',error);}};\nasync function api(path,data){const r=await fetch(path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw new Error(j.error||'Request failed.');return j;}\nconst safeAction=fn=>async()=>{try{await fn();}catch(e){status(e.message,true);}};\nasync function translate(){const source=$('#source'),out=$('#output');if(!source)return;const text=source.value.trim(),from=$('#from').value,to=$('#to').value;if(!text){status('Enter a message first.',true);source.focus();return;}const limit=account.plan==='pro'?1000:500;if([...text].length>limit){status(`Keep this message under ${limit} characters.`,true);return;}const key=JSON.stringify([text,from,to]);const id=++seq;$('#translate').disabled=true;status('Translating your message…');const start=performance.now();try{let result=cache.get(key),cached=!!result;if(!result){result=await api('/api/translate',{text,source:from,target:to});if(cache.size>=20)cache.delete(cache.keys().next().value);cache.set(key,result);}if(id!==seq)return;out.value=result.text;$('#latency').textContent=cached?'From this tab’s memory':`${((performance.now()-start)/1000).toFixed(2)}s · round trip`;status(cached?'Reused your previous translation. No new server request.':'Translation ready. Check names, numbers and tone before sending.');}catch(e){if(id===seq)status(e.message,true);}finally{if(id===seq)$('#translate').disabled=false;}}\nfunction count(){if($('#count'))$('#count').textContent=`${[...$('#source').value].length} / ${account.plan==='pro'?1000:500}`;}\nfunction invalidate(){seq++;if($('#translate'))$('#translate').disabled=false;if($('#output'))$('#output').value='';if($('#latency'))$('#latency').textContent='Measured after translation';count();}\nfunction clear(){if(recognition)recognition.abort();if('speechSynthesis'in window)speechSynthesis.cancel();cache.clear();$('#source').value='';invalidate();status('Draft, translation and this tab’s translation cache cleared.');}\nfunction dictate(){const C=window.SpeechRecognition||window.webkitSpeechRecognition;if(!C){status('Voice input is not supported here. Type or paste your text instead.',true);return;}if(recognizing){recognition.stop();return;}if(!$('#voiceConsent').checked){$('#voiceNotice').hidden=false;$('#voiceConsent').focus();status('Review the voice privacy note and check the box before recording.');return;}recognition=new C();recognition.lang=$('#from').value;recognition.interimResults=true;recognition.continuous=false;let prefix=$('#source').value.trim();recognition.onstart=()=>{recognizing=true;$('#mic').textContent='■ Stop recording';status('Listening… Click Stop recording when done.');};recognition.onresult=e=>{let t='';for(let i=0;i<e.results.length;i++)t+=e.results[i][0].transcript;$('#source').value=(prefix?prefix+' ':'')+t;invalidate();};recognition.onerror=e=>status(e.error==='not-allowed'?'Microphone permission was denied. You can still type.':'Voice input stopped. Try again or type your message.',true);recognition.onend=()=>{recognizing=false;$('#mic').textContent='◉ Voice input';};recognition.start();}\nfunction speak(){if(!('speechSynthesis'in window)){status('Read aloud is unavailable in this browser.',true);return;}const text=$('#output').value;if(!text){status('Translate a message first.',true);return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=$('#to').value;u.rate=.95;u.onerror=()=>status('Read aloud could not start. Check your browser audio settings.',true);speechSynthesis.speak(u);status('Reading aloud. Voice availability depends on your browser.');}\nfunction download(text,name,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}\nasync function accountRefresh(){account=await api('/api/account');if($('#accountState'))$('#accountState').textContent=account.signedIn?`${account.plan==='pro'?'Pro':'Free'} account · ${account.used.toLocaleString()} / ${account.limit.toLocaleString()} Pro characters used this calendar month`:'No account needed for the free translator. Create one when you want to keep subscription access.';for(const e of document.querySelectorAll('[data-signed]'))e.hidden=!account.signedIn;for(const e of document.querySelectorAll('[data-unsigned]'))e.hidden=account.signedIn;if($('#portal'))$('#portal').hidden=account.status==='free';if($('#subscribe'))$('#subscribe').disabled=!account.billing;if($('#billingState'))$('#billingState').textContent=account.billing?'Pro subscriptions are available. Review the terms before checkout.':'Pro is not open for purchase yet. No payment is collected. Free tools are available now.';count();}\nfunction initTranslation(){if(!$('#source'))return;$('#translate').addEventListener('click',translate);$('#source').addEventListener('input',invalidate);$('#from').addEventListener('change',invalidate);$('#to').addEventListener('change',invalidate);$('#source').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();translate();}});$('#swap').addEventListener('click',()=>{let old=$('#from').value;$('#from').value=$('#to').value;$('#to').value=old;const previous=$('#output').value;if(previous)$('#source').value=previous;invalidate();});$('#clear').addEventListener('click',clear);$('#mic').addEventListener('click',safeAction(dictate));$('#speak').addEventListener('click',speak);$('#stopAudio').addEventListener('click',()=>{if('speechSynthesis'in window)speechSynthesis.cancel();});$('#copy').addEventListener('click',safeAction(async()=>{if(!$('#output').value)throw new Error('Translate a message first.');await navigator.clipboard.writeText($('#output').value);status('Translation copied.');}));$('#export').addEventListener('click',()=>{if(!$('#output').value){status('Translate a message first.',true);return;}download($('#output').value,'phrase-lane-translation.txt');status('Text file downloaded.');});document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{$('#source').value=b.dataset.example;invalidate();$('#source').focus();}));const C=window.SpeechRecognition||window.webkitSpeechRecognition;if(!C){$('#mic').disabled=true;$('#mic').title='Voice input is unavailable in this browser. Type or paste instead.';}}\nfunction initAccount(){if(!$('#createAccount'))return;$('#createAccount').addEventListener('click',safeAction(async()=>{$('#createAccount').disabled=true;try{const r=await api('/api/accounts',{});$('#recoveryKey').textContent=r.recoveryKey;$('#keyPanel').hidden=false;await accountRefresh();status('Account created. Save the key now; it is not shown again.');}finally{$('#createAccount').disabled=false;}}));$('#copyKey').addEventListener('click',safeAction(async()=>{await navigator.clipboard.writeText($('#recoveryKey').textContent);status('Account key copied. Save it privately.');}));$('#loginForm').addEventListener('submit',e=>{e.preventDefault();safeAction(async()=>{await api('/api/login',{key:$('#loginKey').value.trim()});$('#loginKey').value='';await accountRefresh();status('Account restored.');})();});$('#logout').addEventListener('click',safeAction(async()=>{await api('/api/logout',{});$('#keyPanel').hidden=true;$('#recoveryKey').textContent='';await accountRefresh();status('Signed out on this browser.');}));$('#subscribe').addEventListener('click',safeAction(async()=>{const r=await api('/api/checkout',{savedKey:$('#savedKey').checked,acceptedTerms:$('#acceptTerms').checked});const u=new URL(r.url);if(u.protocol!=='https:'||u.hostname!=='checkout.stripe.com')throw new Error('Unexpected checkout destination.');location.assign(u.href);}));$('#portal').addEventListener('click',safeAction(async()=>{const r=await api('/api/portal',{});const u=new URL(r.url);if(u.protocol!=='https:'||u.hostname!=='billing.stripe.com')throw new Error('Unexpected billing destination.');location.assign(u.href);}));const checkout=new URLSearchParams(location.search).get('checkout');if(checkout)safeAction(async()=>{await api('/api/sync',{checkout});history.replaceState(null,'','/account');await accountRefresh();status('Payment confirmed. Pro access is active.');})();}\nfunction initSubtitles(){if(!$('#captions'))return;const stamp=n=>{const h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=Math.floor(n%60);return [h,m,s].map(x=>String(x).padStart(2,'0')).join(':')+',000';};$('#makeSrt').addEventListener('click',()=>{const lines=$('#captions').value.split('\\n').map(x=>x.trim()).filter(Boolean);const seconds=Number($('#duration').value);if(!lines.length){status('Write one caption per line.',true);return;}if(lines.length>200||$('#captions').value.length>20000){status('Use up to 200 lines and 20,000 characters.',true);return;}const result=lines.map((line,i)=>`${i+1}\\n${stamp(i*seconds)} --> ${stamp((i+1)*seconds)}\\n${line}\\n`).join('\\n');$('#srtOutput').value=result;status(`${lines.length} captions created. These are evenly timed drafts; adjust timing to your actual video.`);});$('#saveSrt').addEventListener('click',()=>{if(!$('#srtOutput').value){status('Create captions first.',true);return;}download($('#srtOutput').value,'captions.srt');});$('#clearSrt').addEventListener('click',()=>{$('#captions').value='';$('#srtOutput').value='';status('Captions cleared.');});}\ninitTranslation();initAccount();initSubtitles();api('/api/config').then(c=>{config=c;return accountRefresh();}).catch(()=>status('Account status is unavailable. Please reload before using cloud translation.',true));\nwindow.addEventListener('pagehide',()=>{if(recognition)recognition.abort();if('speechSynthesis'in window)speechSynthesis.cancel();cache.clear();});\n\n", "type": "text/javascript; charset=utf-8"}, "/blog/customer-support-replies": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>A calmer workflow for multilingual support replies · PhraseLane</title><meta name=\"description\" content=\"Create a useful first draft while keeping promises and customer data under control.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"A calmer workflow for multilingual support replies\"><meta property=\"og:description\" content=\"Create a useful first draft while keeping promises and customer data under control.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog/customer-support-replies\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog/customer-support-replies\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><a href=\"/blog\">← Back to the Journal</a><p class=\"eyebrow\">CUSTOMER COMMUNICATION</p><h1>A calmer workflow for multilingual support replies</h1><p class=\"meta\">PhraseLane editorial · 2 October 2026 · Practical guide</p><p>Create a useful first draft while keeping promises and customer data under control.</p><h2>Separate the facts from the tone</h2><p>List what you know about the customer’s question before writing a reply. Acknowledge the issue, explain the next action and give a realistic time for an update. Do not add a refund, discount or delivery commitment unless you are authorised to make it. Translation should preserve the promise you actually intend to make.</p><h2>Remove information you do not need</h2><p>A translation usually does not require an order number, address or payment detail. Replace unnecessary personal information with a neutral label before sending text to an external service. Keep the identifying details in your authorised support system and restore them only after the translated draft has been reviewed.</p><h2>Use a small set of clear sentences</h2><p>Try: “Thank you for contacting us. I understand that you could not open the file. Please tell us the device and application you used. We will review the issue and send an update tomorrow.” Adjust the example to match your actual support process. Do not promise a response time you cannot deliver.</p><h2>Review the reply as a complete message</h2><p>After translating, verify the greeting, the request and the next step. Check that a polite sentence has not become an absolute guarantee. If the issue involves safety, legal rights or a disputed charge, use a qualified reviewer and your approved process. Do not rely on a machine-generated response alone.</p><h2>Measure usefulness with real feedback</h2><p>Track whether customers understand the next step and whether your replies reduce repeat questions. Faster drafting is helpful only if it leads to clearer communication. Keep examples free of private customer information when discussing your process with colleagues or creating reusable templates.</p><p><a class=\"button\" href=\"/#workspace\">Try the translator ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/blog/subtitle-draft": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Make an SRT subtitle draft from plain text · PhraseLane</title><meta name=\"description\" content=\"Build a simple caption file, then adjust its timing against the actual video.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Make an SRT subtitle draft from plain text\"><meta property=\"og:description\" content=\"Build a simple caption file, then adjust its timing against the actual video.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog/subtitle-draft\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog/subtitle-draft\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><a href=\"/blog\">← Back to the Journal</a><p class=\"eyebrow\">CREATOR NOTES</p><h1>Make an SRT subtitle draft from plain text</h1><p class=\"meta\">PhraseLane editorial · 2 October 2026 · Practical guide</p><p>Build a simple caption file, then adjust its timing against the actual video.</p><h2>Write one thought per line</h2><p>An SRT file contains numbered captions, timing information and text. Start with a plain-text transcript and divide it into readable chunks. Avoid long lines that occupy the whole screen. Our subtitle maker turns each non-empty input line into one caption; it does not listen to your video or automatically recognise speech.</p><h2>Choose a starting duration</h2><p>Select the number of seconds to give each caption. The tool places captions consecutively from the beginning of the timeline. This gives you a draft structure quickly, but speaking pace varies. The generated times are placeholders based on your selected duration, not a claim that the subtitles are synchronised.</p><h2>Export and check in your editor</h2><p>Create the captions and download the .srt file. Import it into an editor that supports SRT. Play the video from the beginning and move caption boundaries to match the speech. Check quiet sections, overlapping dialogue and transitions. Save a copy of the edited file separately from the draft.</p><h2>Translate with context</h2><p>When making another language version, translate complete sentences first and then divide them into readable captions. Word order and text length can change across languages. Keep the original transcript for reference, and verify names, specialist vocabulary and any claims. Machine translation is a draft, not an accessibility or localisation certification.</p><h2>Keep rights and privacy in mind</h2><p>Only create subtitles for material you are authorised to use. The subtitle generator itself runs in the page without uploading the caption text to our server. If you separately send text through the cloud translator, the translation privacy policy applies. Review timing and readability before publishing your final video.</p><p><a class=\"button\" href=\"/#workspace\">Try the translator ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/blog/translate-client-messages": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Write client messages that translate clearly · PhraseLane</title><meta name=\"description\" content=\"Small changes to your original message can make a translation easier to check and less likely to miss your intent.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Write client messages that translate clearly\"><meta property=\"og:description\" content=\"Small changes to your original message can make a translation easier to check and less likely to miss your intent.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog/translate-client-messages\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog/translate-client-messages\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><a href=\"/blog\">← Back to the Journal</a><p class=\"eyebrow\">WORKING ACROSS BORDERS</p><h1>Write client messages that translate clearly</h1><p class=\"meta\">PhraseLane editorial · 2 October 2026 · Practical guide</p><p>Small changes to your original message can make a translation easier to check and less likely to miss your intent.</p><h2>Start with one request</h2><p>A translation tool cannot resolve an unclear instruction. Before you translate, ask yourself what the recipient needs to do next. Keep one main request per paragraph. A useful message names the task, gives a deadline and explains what a reply should contain. “Please review the attached draft and confirm the delivery date” is easier to act on than “Let me know what you think when you can.”</p><h2>Make dates and quantities unambiguous</h2><p>Write out month names when a numeric date could be read in more than one way. Add a time zone for a deadline. Keep quantities next to their units and name the currency when discussing a price. Translate the message, then compare these details against the original. Do not assume a fluent sentence proves that every number survived correctly.</p><h2>Replace idioms with direct language</h2><p>Expressions such as “touch base” or “move the goalposts” can become confusing outside their original context. Try “discuss the project” or “change the agreed requirements.” Direct language does not need to sound cold: a short thank-you and a clear request are usually enough. If the tone matters, ask a speaker of the target language to review the result.</p><h2>A message you can adapt</h2><p>Try: “Thank you for reviewing the draft. Could you confirm whether the headings are correct? Please send your feedback by 5 October at 16:00 UTC. I will send the revised version after your reply.” Replace the details, translate it and check the output line by line. This is a writing example, not an approved legal or contractual template.</p><h2>Use a human check when the stakes rise</h2><p>Routine project messages are a useful place to start. Contracts, medical information, safety instructions and official documents need qualified review. PhraseLane produces machine translations; it does not certify them. Keep confidential customer information out of a cloud translation request unless you are authorised to share it.</p><p><a class=\"button\" href=\"/#workspace\">Try the translator ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/blog/translation-privacy": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Before you paste: a translation privacy checklist · PhraseLane</title><meta name=\"description\" content=\"Know which tool processes your text and decide what should stay out of it.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Before you paste: a translation privacy checklist\"><meta property=\"og:description\" content=\"Know which tool processes your text and decide what should stay out of it.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog/translation-privacy\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog/translation-privacy\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><a href=\"/blog\">← Back to the Journal</a><p class=\"eyebrow\">PRIVACY BY PRACTICE</p><h1>Before you paste: a translation privacy checklist</h1><p class=\"meta\">PhraseLane editorial · 2 October 2026 · Practical guide</p><p>Know which tool processes your text and decide what should stay out of it.</p><h2>Identify the processing route</h2><p>Different tools move information differently. PhraseLane sends a cloud translation request to its Cloudflare Worker and Workers AI. Voice input may be processed by your browser provider. Reading aloud depends on the voices available in your browser or operating system. The local subtitle maker formats text in the page.</p><h2>Remove secrets and unnecessary details</h2><p>Do not paste passwords, authentication codes, payment card details or documents that you are not authorised to share. For an ordinary customer message, replace names and account references before translation when they are not needed for meaning. Keep your original in the system where it belongs.</p><h2>Understand what we retain</h2><p>The application does not intentionally store translation input, translation output or raw audio in its database. It does store account identifiers, hashed access keys and usage counters where those features are used. Cloudflare and browser providers may process technical data under their own policies. No claim of total anonymity or end-to-end encryption is made.</p><h2>Remember shared devices</h2><p>Your signed-in account uses a secure session cookie. Sign out when using a shared computer. Your account recovery key is a credential: anyone with it can restore access, so keep it in a password manager and do not include it in a translation. The tool does not automatically save that key to local storage.</p><h2>Use a specialist route for sensitive work</h2><p>Some information belongs in an approved organisational translation workflow. Check your employer’s or client’s requirements before handling confidential material. If you need a contractual data-processing agreement, regulated-document workflow or certified translation, do not assume this public beta provides it. Contact the operator with questions before sending the material.</p><p><a class=\"button\" href=\"/#workspace\">Try the translator ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/blog/translation-speed": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>What actually makes a translation feel fast? · PhraseLane</title><meta name=\"description\" content=\"Understand waiting time without confusing an attractive demo with guaranteed performance.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"What actually makes a translation feel fast?\"><meta property=\"og:description\" content=\"Understand waiting time without confusing an attractive demo with guaranteed performance.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog/translation-speed\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog/translation-speed\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><a href=\"/blog\">← Back to the Journal</a><p class=\"eyebrow\">A PRACTICAL GUIDE</p><h1>What actually makes a translation feel fast?</h1><p class=\"meta\">PhraseLane editorial · 2 October 2026 · Practical guide</p><p>Understand waiting time without confusing an attractive demo with guaranteed performance.</p><h2>Look at the whole round trip</h2><p>A translation request includes your network connection, the service queue, model processing and delivery of the result. PhraseLane displays the measured round-trip time after a successful request. This is a measurement for that request, not a speed promise for the next one. Wi-Fi quality, language pair and service load can all change your experience.</p><h2>Keep the unit of work small</h2><p>Short, complete messages are easier to review and quicker to work with than a whole document pasted into one box. Split a long message at paragraph boundaries, not in the middle of a sentence. Keeping related context together matters more than chasing the shortest possible chunk. Free cloud translations are limited to 500 characters per request.</p><h2>Avoid sending on every keystroke</h2><p>Sending a request for every letter can waste your allowance and cause results to arrive out of order. PhraseLane translates when you press the button or use Ctrl/Command + Enter. If you change the text while a request is running, the old result is not inserted into your new draft. This keeps the screen consistent with your latest input.</p><h2>Reuse work carefully</h2><p>PhraseLane can reuse recent translations from the current tab’s memory when the text and both language choices match exactly. It labels a reused result so you know it was not a fresh server request. The cache is not written to browser storage. Clear the workspace or close the tab to discard it.</p><h2>Speed is not accuracy</h2><p>Fast output still needs review. Set aside time to check names, currencies, dates and tone. Use short everyday messages to evaluate whether the service fits your workflow. This launch does not provide simultaneous interpretation, audio-to-audio streaming or a latency service-level agreement.</p><p><a class=\"button\" href=\"/#workspace\">Try the translator ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/blog/voice-notes-to-clear-text": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Turn a voice note into a clear written message · PhraseLane</title><meta name=\"description\" content=\"A short dictation workflow for people who think faster than they type.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Turn a voice note into a clear written message\"><meta property=\"og:description\" content=\"A short dictation workflow for people who think faster than they type.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog/voice-notes-to-clear-text\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog/voice-notes-to-clear-text\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><a href=\"/blog\">← Back to the Journal</a><p class=\"eyebrow\">VOICE & WORKFLOW</p><h1>Turn a voice note into a clear written message</h1><p class=\"meta\">PhraseLane editorial · 2 October 2026 · Practical guide</p><p>A short dictation workflow for people who think faster than they type.</p><h2>Decide the point before recording</h2><p>Start with a single sentence explaining why you are speaking. A voice note usually works better when you separate the context, request and next step. A few seconds of planning helps you avoid long pauses and repeated thoughts. PhraseLane uses your browser’s speech recognition where it is available; you can always type or paste instead.</p><h2>Record only with permission</h2><p>Use the microphone for your own voice, or obtain appropriate permission before recording another person. Browser speech recognition may send audio to the browser provider. Read the privacy note before turning it on. Do not use this workflow for confidential meetings or personal information without understanding the processing involved.</p><h2>Check the transcript before translating</h2><p>Speech recognition can mix up names, numbers and words that sound similar. Read the transcript while comparing it with what you meant to say. Add punctuation and replace vague references such as “that thing” with the actual project or item. Keep the first message short; you can add context in a second paragraph.</p><h2>Translate, then listen once</h2><p>Choose the source and target languages explicitly. Translate your corrected text, then use read aloud if your browser supports the target language. Listening can help you notice missing phrases, but it does not independently verify meaning. Compare dates and quantities with the original and use a fluent reviewer for important communications.</p><h2>Keep a text fallback ready</h2><p>Microphone permissions, device settings and browser support can interrupt dictation. If recording does not start, stop trying repeatedly and use the text field. Do not leave the microphone running while troubleshooting. PhraseLane stops its recognition session when you leave the page; you can also stop recording with the visible button.</p><p><a class=\"button\" href=\"/#workspace\">Try the translator ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/blog": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>The Journal · PhraseLane</title><meta name=\"description\" content=\"Practical guides to clear multilingual messages, voice notes, privacy and subtitles.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"The Journal\"><meta property=\"og:description\" content=\"Practical guides to clear multilingual messages, voice notes, privacy and subtitles.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/blog\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"wrap\"><header class=\"hero\"><div><span class=\"eyebrow\">The PhraseLane Journal</span><h1>Work in<br><em>more words.</em></h1></div><p>Original, practical notes on communicating across languages. No shortcuts around clarity.</p></header><div class=\"grid3\"><article class=\"card\"><span class=\"eyebrow\">WORKING ACROSS BORDERS</span><h2><a href=\"/blog/translate-client-messages\">Write client messages that translate clearly</a></h2><p>Small changes to your original message can make a translation easier to check and less likely to miss your intent.</p><a href=\"/blog/translate-client-messages\">Read the guide ↗</a></article><article class=\"card\"><span class=\"eyebrow\">VOICE & WORKFLOW</span><h2><a href=\"/blog/voice-notes-to-clear-text\">Turn a voice note into a clear written message</a></h2><p>A short dictation workflow for people who think faster than they type.</p><a href=\"/blog/voice-notes-to-clear-text\">Read the guide ↗</a></article><article class=\"card\"><span class=\"eyebrow\">A PRACTICAL GUIDE</span><h2><a href=\"/blog/translation-speed\">What actually makes a translation feel fast?</a></h2><p>Understand waiting time without confusing an attractive demo with guaranteed performance.</p><a href=\"/blog/translation-speed\">Read the guide ↗</a></article><article class=\"card\"><span class=\"eyebrow\">CREATOR NOTES</span><h2><a href=\"/blog/subtitle-draft\">Make an SRT subtitle draft from plain text</a></h2><p>Build a simple caption file, then adjust its timing against the actual video.</p><a href=\"/blog/subtitle-draft\">Read the guide ↗</a></article><article class=\"card\"><span class=\"eyebrow\">CUSTOMER COMMUNICATION</span><h2><a href=\"/blog/customer-support-replies\">A calmer workflow for multilingual support replies</a></h2><p>Create a useful first draft while keeping promises and customer data under control.</p><a href=\"/blog/customer-support-replies\">Read the guide ↗</a></article><article class=\"card\"><span class=\"eyebrow\">PRIVACY BY PRACTICE</span><h2><a href=\"/blog/translation-privacy\">Before you paste: a translation privacy checklist</a></h2><p>Know which tool processes your text and decide what should stay out of it.</p><a href=\"/blog/translation-privacy\">Read the guide ↗</a></article></div></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/contact": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>A direct line · PhraseLane</title><meta name=\"description\" content=\"A direct line\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"A direct line\"><meta property=\"og:description\" content=\"A direct line\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/contact\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/contact\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><h1>A direct line</h1><p>Questions about the tools, a translation issue or your account? Contact the operator at <a href=\"mailto:fmfm.stars@gmail.com\">fmfm.stars@gmail.com</a>.</p><h2>Tell us what happened</h2><p>Include the tool name, your browser and a description of the issue. Use a non-sensitive example if a translation behaved unexpectedly. Do not send recovery keys, passwords, payment card details or confidential documents.</p><h2>Account and billing requests</h2><p>For data access, deletion or billing questions, describe your request without sharing your private account key. Identity verification may be needed before account changes. No fixed response-time promise is made during this beta.</p><h2>Report a security issue</h2><p>Send a brief description and steps that demonstrate the problem without accessing another person’s data. Do not perform disruptive testing. We will investigate reports, but this is not a paid bug-bounty programme.</p><p><a class=\"button secondary\" href=\"/\">Return to the tools ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/favicon.svg": {"content": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"64\" height=\"64\" viewBox=\"0 0 64 64\"><rect width=\"64\" height=\"64\" rx=\"18\" fill=\"#175e4b\"/><path d=\"M20 44 44 20M22 20h22v22\" fill=\"none\" stroke=\"#e6f0cc\" stroke-width=\"6\"/></svg>\n", "type": "image/svg+xml"}, "/": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Make yourself understood · PhraseLane</title><meta name=\"description\" content=\"Translate short messages, dictate text and create subtitle drafts. Practical language tools for international work.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Make yourself understood\"><meta property=\"og:description\" content=\"Translate short messages, dictate text and create subtitle drafts. Practical language tools for international work.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"><script src=\"/app.js\" defer></script></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"wrap\"><header class=\"hero\"><div><div class=\"eyebrow\"><span class=\"dot\"></span> For work without language barriers</div><h1>Good words.<br><em>Fewer borders.</em></h1></div><div class=\"heroaside\"><p>A focused workspace for the messages that move your day forward. Translate, speak and share—with room to think.</p><div class=\"note\">01 / Write it. Translate it. Make it yours.</div></div></header><section id=\"workspace\" class=\"workspace\" aria-label=\"Translation workspace\"><div class=\"workhead\"><div class=\"tabs\"><a class=\"active\" href=\"/#workspace\">Text & voice</a><a href=\"/tools/subtitle-maker\">Subtitle maker ↗</a></div><span class=\"badge\">PUBLIC BETA · 12 LANGUAGES</span></div><div class=\"panels\"><div class=\"pane\"><div class=\"langbar\"><div><label for=\"from\">TRANSLATE FROM</label><br><select id=\"from\"><option value=\"en\" selected>English</option><option value=\"es\">Spanish</option><option value=\"fr\">French</option><option value=\"de\">German</option><option value=\"it\">Italian</option><option value=\"pt\">Portuguese</option><option value=\"ja\">Japanese</option><option value=\"ko\">Korean</option><option value=\"zh\">Chinese</option><option value=\"ar\">Arabic</option><option value=\"hi\">Hindi</option><option value=\"nl\">Dutch</option></select></div><button class=\"iconbtn\" id=\"swap\" aria-label=\"Swap languages\">⇄</button></div><label class=\"micro\" for=\"source\">Your message</label><textarea id=\"source\" placeholder=\"Write something worth understanding…\" maxlength=\"2000\" spellcheck=\"true\"></textarea><div class=\"panebottom\"><button class=\"iconbtn\" id=\"mic\">◉ Voice input</button><button class=\"iconbtn\" id=\"clear\">Clear</button><span class=\"counter\" id=\"count\">0 / 500</span></div></div><div class=\"pane\"><div class=\"langbar\"><div><label for=\"to\">TRANSLATE INTO</label><br><select id=\"to\"><option value=\"en\">English</option><option value=\"es\" selected>Spanish</option><option value=\"fr\">French</option><option value=\"de\">German</option><option value=\"it\">Italian</option><option value=\"pt\">Portuguese</option><option value=\"ja\">Japanese</option><option value=\"ko\">Korean</option><option value=\"zh\">Chinese</option><option value=\"ar\">Arabic</option><option value=\"hi\">Hindi</option><option value=\"nl\">Dutch</option></select></div><span class=\"badge\" id=\"latency\">Measured after translation</span></div><label class=\"micro\" for=\"output\">Translation</label><textarea id=\"output\" readonly placeholder=\"Your translation will appear here.\" aria-label=\"Translation result\" dir=\"auto\"></textarea><div class=\"panebottom\"><button class=\"iconbtn\" id=\"copy\">Copy</button><button class=\"iconbtn\" id=\"speak\">▷ Read aloud</button><button class=\"iconbtn\" id=\"stopAudio\">Stop audio</button><button class=\"iconbtn\" id=\"export\">↓ .txt</button></div></div></div><div class=\"workfoot\"><div><div id=\"status\" class=\"status\" role=\"status\" aria-live=\"polite\">Ready when you are.</div><div class=\"micro\">Cloud translation · 10 requests / day per network · 500 characters each · Ctrl/⌘ + Enter</div></div><button class=\"button\" id=\"translate\">Translate message <span>↗</span></button></div></section><div id=\"voiceNotice\" class=\"notice\" hidden><label class=\"check\"><input id=\"voiceConsent\" type=\"checkbox\">I understand that my browser provider may process my microphone audio. I have permission to record this speech.</label><p>Check this box, then press Voice input again. Audio is not saved by PhraseLane. Browser support and languages vary.</p></div><div class=\"quickstart\"><span class=\"micro\">START WITH A MESSAGE</span><button class=\"chip\" data-example=\"Thank you for your message. I will send the updated file tomorrow.\">A client reply ↗</button><button class=\"chip\" data-example=\"Could you confirm the meeting time and your time zone?\">A meeting check-in ↗</button><button class=\"chip\" data-example=\"Hello! Does this room have a quiet space for a video call?\">A travel question ↗</button></div><div class=\"trustrow\"><span>↗ No account needed to try</span><span>◈ Your drafts are not stored in our database</span><span>◎ Actual request time shown</span></div><section class=\"section\"><div class=\"sectionhead\"><div><span class=\"eyebrow\">Small tools. Everyday momentum.</span><h2>One less thing in your way.</h2></div></div><div class=\"grid3\"><article class=\"card\"><span class=\"number\">01 / TRANSLATE</span><h3>Find the right words.</h3><p>Translate short messages between 12 languages. Keep control of the original and check the result before sharing.</p></article><article class=\"card\"><span class=\"number\">02 / SPEAK</span><h3>Think out loud.</h3><p>Dictate in supported browsers, edit the transcript and listen to the translation. A text fallback is always there.</p></article><article class=\"card\"><span class=\"number\">03 / CAPTION</span><h3>Give your words a timeline.</h3><p>Turn one caption per line into an SRT draft. Adjust the timing in your video editor before publishing.</p><a href=\"/tools/subtitle-maker\">Open subtitle maker ↗</a></article></div></section><section class=\"banner\"><div><span class=\"eyebrow\">Built for a considered workflow</span><h2>Short messages. Clear intent.</h2><p>Machine translation is a starting point. Review names, numbers and tone; use a qualified translator for high-stakes documents.</p></div><a class=\"button secondary\" href=\"/blog/translate-client-messages\">A better writing workflow ↗</a></section><section class=\"section\"><div class=\"sectionhead\"><div><span class=\"eyebrow\">The PhraseLane Journal</span><h2>A few words on better work.</h2></div><a href=\"/blog\">All guides ↗</a></div><div class=\"grid3\"><article class=\"card\"><div class=\"graphic\" aria-hidden=\"true\">Aa</div><span class=\"eyebrow\">WORKING ACROSS BORDERS</span><h3><a href=\"/blog/translate-client-messages\">Write client messages that translate clearly</a></h3><p>Small changes to your original message can make a translation easier to check and less likely to miss your intent.</p><a href=\"/blog/translate-client-messages\">Read the guide ↗</a></article><article class=\"card\"><div class=\"graphic\" aria-hidden=\"true\">∿</div><span class=\"eyebrow\">VOICE & WORKFLOW</span><h3><a href=\"/blog/voice-notes-to-clear-text\">Turn a voice note into a clear written message</a></h3><p>A short dictation workflow for people who think faster than they type.</p><a href=\"/blog/voice-notes-to-clear-text\">Read the guide ↗</a></article><article class=\"card\"><div class=\"graphic\" aria-hidden=\"true\">↗</div><span class=\"eyebrow\">A PRACTICAL GUIDE</span><h3><a href=\"/blog/translation-speed\">What actually makes a translation feel fast?</a></h3><p>Understand waiting time without confusing an attractive demo with guaranteed performance.</p><a href=\"/blog/translation-speed\">Read the guide ↗</a></article></div></section></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/legal": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Seller information / 特定商取引法に基づく表記 · PhraseLane</title><meta name=\"description\" content=\"Seller information / 特定商取引法に基づく表記\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Seller information / 特定商取引法に基づく表記\"><meta property=\"og:description\" content=\"Seller information / 特定商取引法に基づく表記\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/legal\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/legal\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><h1>Seller information / 特定商取引法に基づく表記</h1><div class=\"notice\">Paid subscriptions are not open for purchase. No payment is collected by this website at launch.</div><h2>Operator disclosures</h2><!--SELLER--><p>Before paid sales open, the seller’s legal name, business address, reachable telephone number, contact details and confirmed transaction terms will be displayed here. These details have not yet been supplied for this product.</p><h2>Planned service and charges</h2><p>PhraseLane Pro is planned as a monthly digital translation subscription at $9 USD, subject to the limits on the pricing page. Additional tax, if applicable, must be shown before purchase. An internet connection and compatible browser are required and are the customer’s responsibility.</p><h2>Billing, delivery and cancellation</h2><p>Once enabled, secure hosted checkout will handle payment. Access is activated after server-side payment confirmation. Monthly renewal continues until cancelled through the billing portal. Cancellation prevents future renewal; refunds can be requested through the contact page, subject to applicable consumer rights.</p><p>有料販売は未開始です。販売事業者の正式名称・住所・電話番号などの確認と表示、決済の動作確認が完了するまで購入を受け付けません。</p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/pricing": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Simple, bounded pricing · PhraseLane</title><meta name=\"description\" content=\"Try the free translation tools. Pro is planned at $9 per month with clear usage limits.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Simple, bounded pricing\"><meta property=\"og:description\" content=\"Try the free translation tools. Pro is planned at $9 per month with clear usage limits.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/pricing\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/pricing\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"wrap\"><header class=\"hero\"><div><span class=\"eyebrow\">Start with something useful</span><h1>A little help.<br><em>A clear limit.</em></h1></div><p>Use the free tools today. Pro is planned at $9 USD per month; paid subscriptions are not open yet.</p></header><div class=\"grid3\"><section class=\"card\"><span class=\"eyebrow\">Free beta</span><h2>Everyday</h2><div class=\"price\">$0</div><ul class=\"featurelist\"><li>10 cloud translations per network / day</li><li>500 characters per translation</li><li>12 language choices</li><li>Browser voice input and read aloud where supported</li><li>Local SRT draft maker</li><li>Copy and text downloads</li></ul><a class=\"button\" href=\"/#workspace\">Try the free tools ↗</a></section><section class=\"card\"><span class=\"eyebrow\">Planned · Not yet on sale</span><h2>Pro</h2><div class=\"price\">$9 <span>USD / month</span></div><ul class=\"featurelist\"><li>50,000 cloud input characters / calendar month</li><li>Up to 1,000 characters per translation</li><li>Up to 100 requests per day</li><li>Private account key for access</li><li>Monthly renewal; cancel through billing portal</li><li>All free tools included</li></ul><a class=\"button secondary\" href=\"/account\">View account & availability ↗</a><p class=\"micro\">Pro checkout stays closed until billing, seller disclosures and end-to-end payment testing are complete.</p></section><section class=\"card\"><span class=\"eyebrow\">Good to know</span><h2>Useful, with boundaries.</h2><p>Allowances reset at 00:00 UTC. A shared daily cloud capacity limit protects this beta; translations can pause when that capacity is reached.</p><p>No overage charges are added by this app. Unused monthly characters do not roll over. Any applicable tax must be shown before a future purchase.</p><p>No guaranteed latency, certified translation or simultaneous interpretation. Browser voice features vary by device.</p><a href=\"/terms\">Read the terms →</a></section></div></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/privacy": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Privacy, plainly · PhraseLane</title><meta name=\"description\" content=\"Privacy, plainly\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Privacy, plainly\"><meta property=\"og:description\" content=\"Privacy, plainly\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/privacy\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/privacy\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><h1>Privacy, plainly</h1><p>Updated 2 October 2026. This page describes the current public beta, not a promise of complete anonymity.</p><h2>Translation and voice</h2><p>Cloud translations send the text and selected languages to our Cloudflare Worker and Cloudflare Workers AI. We do not intentionally write translation input or output to our application database, logs or analytics. Recent identical translations may be kept in the current tab’s memory until you clear it or leave. Cloudflare may process technical data under its own policies.</p><p>Voice input uses your browser’s speech recognition and may send audio to its provider. We ask for acknowledgement before starting the microphone. Read aloud uses browser or operating-system voices, which may use remote services. We do not receive or store raw microphone audio. Browser and device support vary.</p><h2>Local subtitle tool</h2><p>Caption formatting happens in your browser. Its caption text is not uploaded by that tool. If you separately use cloud translation, the translation processing above applies.</p><h2>Account and usage</h2><p>Optional accounts store a random account ID, a hash of the recovery key, creation time, session hashes and any subscription identifiers and status. A secure, HttpOnly, SameSite session cookie keeps you signed in for up to 30 days. Usage controls retain salted hashes derived from network addresses and counters, not the text. Daily records expire after about two days; monthly allowance records expire after about 62 days. An automated cleanup removes expired records.</p><h2>Payments</h2><p>Paid checkout is currently closed. When enabled, Stripe will handle payment details, billing contact information and subscription management on its hosted pages. We do not receive full card numbers. Stripe and our infrastructure providers have their own privacy policies.</p><h2>Your choices</h2><p>You can use free translation without an account. Clear removes the current draft and translation cache; sign out invalidates this browser’s session. Contact us from the contact page for account data access or deletion. Identity must be verified, and transaction records may need to be retained when applicable obligations require it. Do not email your recovery key.</p><h2>No advertising tracking</h2><p>This launch contains no advertising tags, third-party analytics scripts or marketing cookies. We do not sell your translation text. Use an approved specialist workflow for confidential or regulated material. No absolute security or compliance guarantee is made.</p><p>Provider information: <a href=\"https://www.cloudflare.com/privacypolicy/\">Cloudflare privacy policy</a> and <a href=\"https://stripe.com/privacy\">Stripe privacy policy</a>.</p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/style.css": {"content": ":root{--ink:#182b3a;--muted:#60727c;--paper:#f6f5f0;--white:#fff;--line:#dfe5df;--green:#175e4b;--lime:#e6f0cc;--orange:#ec6c49;--mono:ui-monospace,SFMono-Regular,Consolas,monospace}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}a{color:inherit}button,input,textarea,select{font:inherit}button,a,textarea,select,input{outline-offset:4px}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid var(--orange)}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}nav{max-width:1240px;margin:auto;min-height:86px;display:flex;align-items:center;justify-content:space-between;padding:20px 32px;border-bottom:1px solid var(--line);gap:20px}.brand{text-decoration:none;font-size:23px;font-weight:790;letter-spacing:-1px;display:flex;align-items:center;gap:10px}.mark{background:var(--green);color:white;display:inline-grid;place-items:center;width:34px;height:34px;border-radius:10px;font-size:22px}.navlinks{display:flex;align-items:center;gap:28px;font-size:14px}.navlinks a{text-decoration:none}.navlinks a:hover{color:var(--green)}.smallbtn{border:1px solid var(--line);padding:8px 16px;border-radius:8px}.wrap{max-width:1180px;margin:auto;padding:0 28px}.hero{display:grid;grid-template-columns:1.3fr 1fr;gap:45px;align-items:end;padding:64px 0 36px}.eyebrow{font:11px/1.6 var(--mono);text-transform:uppercase;letter-spacing:2px;color:var(--green);display:flex;gap:9px;align-items:center}.dot{width:7px;height:7px;border-radius:50%;background:var(--green)}h1{font-size:clamp(38px,5vw,66px);line-height:1.05;letter-spacing:-3px;margin:18px 0 20px;font-weight:660}h1 em{font:italic 1.03em Georgia,serif;color:var(--green)}.hero p{max-width:460px;color:var(--muted);margin-bottom:12px}.heroaside{padding:0 0 8px 36px;border-left:1px solid var(--line)}.heroaside .note{font:12px var(--mono);margin-top:20px;color:var(--green)}.workspace{background:white;border:1px solid var(--line);border-radius:16px;box-shadow:0 14px 35px #1b383809;overflow:hidden}.workhead{padding:17px 24px;display:flex;justify-content:space-between;align-items:center;gap:14px;background:#fafbf7;border-bottom:1px solid var(--line)}.tabs{display:flex;gap:7px;font-size:13px;align-items:center}.tabs a{padding:7px 14px;text-decoration:none;border-radius:6px}.tabs .active{background:var(--green);color:white}.badge{font:11px var(--mono);color:var(--muted);white-space:nowrap}.panels{display:grid;grid-template-columns:1fr 1fr}.pane{min-width:0;padding:22px 25px}.pane+.pane{border-left:1px solid var(--line);background:#fcfdfb}.langbar{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:17px}.langbar label{font-size:12px;color:var(--muted)}select{border:1px solid var(--line);background:white;border-radius:6px;padding:7px 28px 7px 10px;color:var(--ink);max-width:100%}.iconbtn{background:white;border:1px solid var(--line);border-radius:6px;padding:6px 10px;color:var(--ink)}textarea{width:100%;height:210px;border:0;resize:vertical;color:var(--ink);background:transparent;line-height:1.65;font-size:19px;padding:8px 0}textarea::placeholder{color:#94a09f}.panebottom{display:flex;gap:8px;align-items:center;flex-wrap:wrap;min-height:42px}.counter{margin-left:auto;font:11px var(--mono);color:var(--muted)}.workfoot{border-top:1px solid var(--line);padding:18px 24px;display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.button{display:inline-flex;align-items:center;justify-content:center;gap:16px;border:0;background:var(--green);color:white;padding:12px 22px;border-radius:7px;text-decoration:none;font-weight:600;font-size:14px}.button.secondary{background:var(--lime);color:var(--green)}.button.dark{background:var(--ink)}.micro{font-size:11px;color:var(--muted);line-height:1.7}.status{font-size:13px;min-height:22px;white-space:pre-wrap}.status.error{color:#9a291c}.quickstart{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:20px 0;font-size:12px}.chip{border:1px solid var(--line);background:transparent;border-radius:30px;padding:7px 13px;color:var(--muted);font-size:12px}.chip:hover{background:var(--lime);color:var(--green)}.trustrow{display:flex;gap:25px;justify-content:space-between;border-bottom:1px solid var(--line);padding:16px 0 37px;font-size:12px;color:var(--muted)}.section{padding:62px 0}h2{font-size:32px;letter-spacing:-1px;line-height:1.2;font-weight:650;margin:10px 0 18px}h3{font-size:20px;line-height:1.35}.sectionhead{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:26px}.sectionhead a{font-size:13px;color:var(--green)}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{padding:28px;background:white;border:1px solid var(--line);border-radius:12px}.card .number{font:12px var(--mono);color:var(--green)}.card p{font-size:14px;color:var(--muted)}.card a{text-decoration:none}.card a:hover{text-decoration:underline}.graphic{height:150px;border-radius:8px;background:var(--lime);display:grid;place-items:center;margin-bottom:20px;font:italic 50px Georgia;color:var(--green)}.card:nth-child(2) .graphic{background:#e9e8f5;color:#505271}.card:nth-child(3) .graphic{background:#f7e6dc;color:#934c32}.banner{background:var(--ink);color:#fff;border-radius:12px;padding:32px;display:flex;justify-content:space-between;align-items:center;gap:22px}.banner p{color:#c0d0d0;font-size:14px;max-width:580px}.banner .eyebrow{color:#d4e2bd}footer{border-top:1px solid var(--line);margin-top:55px;padding:28px 32px;color:var(--muted);font-size:12px}.footerinner{max-width:1124px;margin:auto;display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap}.footlinks{display:flex;gap:18px}.article{max-width:760px;margin:60px auto;padding:0 26px}.article h1{font-size:44px;letter-spacing:-1.8px}.article h2{font-size:25px;margin-top:36px}.article p,.article li{color:#40535e}.article a{color:var(--green)}.article pre{white-space:pre-wrap;background:#e8ede7;padding:20px;border-radius:8px}.article .meta{font:12px var(--mono);color:var(--muted)}.price{font-size:48px;font-weight:700;letter-spacing:-2px}.price span{font-size:14px;font-weight:400;letter-spacing:0}.featurelist{padding-left:20px;font-size:14px}.notice{background:#eef2e7;padding:18px;border-radius:8px;color:var(--green);font-size:14px}.field{display:block;width:100%;padding:11px;border:1px solid var(--line);border-radius:6px;margin:10px 0}.accountbox{max-width:660px;margin:45px auto}.accountbox .card{margin-bottom:20px}.key{font:12px var(--mono);word-break:break-all;background:#eef2e7;padding:18px;border-radius:6px}.row{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.check{display:flex;gap:10px;align-items:flex-start;font-size:13px;margin:16px 0}.check input{margin-top:6px}.hidden,[hidden]{display:none!important}.skip{position:absolute;left:15px;top:-70px;z-index:5;background:white;padding:10px}.skip:focus{top:5px}dt{font-weight:700}dd{margin-left:0;margin-bottom:15px}@media(max-width:760px){nav{padding:17px 20px}.navlinks{gap:14px}.navlinks .optional{display:none}.wrap{padding:0 18px}.hero{grid-template-columns:1fr;gap:16px;padding-top:36px}.heroaside{border:0;padding:0}.heroaside p{margin-top:0}h1{letter-spacing:-2px;font-size:45px}.panels{grid-template-columns:1fr}.pane+.pane{border-left:0;border-top:1px solid var(--line)}.pane{padding:18px}textarea{height:160px}.workhead{padding:12px;align-items:start}.tabs a{padding:7px 10px}.badge{font-size:9px}.workfoot{padding:17px}.trustrow{gap:12px;flex-wrap:wrap}.grid3{grid-template-columns:1fr}.section{padding:37px 0}.banner{display:block;padding:25px}.banner .button{margin-top:10px}.article{margin-top:35px}.article h1{font-size:36px}.footerinner{display:block}.footlinks{flex-wrap:wrap;margin-top:15px}.sectionhead{align-items:start}.sectionhead h2{font-size:27px}}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}\n\n", "type": "text/css; charset=utf-8"}, "/terms": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Terms of use · PhraseLane</title><meta name=\"description\" content=\"Terms of use\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Terms of use\"><meta property=\"og:description\" content=\"Terms of use\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/terms\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/terms\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><h1>Terms of use</h1><p>Updated 2 October 2026. PhraseLane is an early-stage language utility for adults aged 18 and over. By using the service, use it only for lawful purposes and material you are authorised to process.</p><h2>Free beta</h2><p>The free cloud service provides up to 10 requests per network address per UTC day, with 500 input characters per request. A shared daily capacity limit may temporarily pause cloud translation. Local tools and browser voice capabilities have their own limits. Availability, latency and translation quality are not guaranteed.</p><h2>Planned Pro subscription</h2><p>Paid subscriptions are not currently offered. If opened, the proposed plan is $9 USD per month with monthly renewal until cancelled, 50,000 input characters per calendar month, up to 1,000 characters per request and up to 100 requests per day. No unused allowance rolls over. No paid overage is automatically added by the app. Final price, any tax and renewal terms must be displayed before checkout.</p><p>Cancellation through the billing portal stops future renewal; access normally continues until the paid period ends. Refund requests can be submitted through the contact page. Mandatory consumer rights remain applicable, and no blanket exclusion of those rights is intended. A purchase will not be enabled until the operator’s sale disclosures are completed.</p><h2>Review before relying on output</h2><p>Machine translation can contain errors or omit context. You are responsible for reviewing names, numbers, tone and meaning. The service does not provide certified translation, medical advice, legal advice, emergency interpretation or safety-critical instructions. Use qualified human review for high-stakes work.</p><h2>Fair and safe use</h2><p>Do not bypass rate limits, attack the service, upload material you have no right to share, impersonate others, conduct fraud or record others without appropriate permission. Access can be limited for abuse or security reasons. The service is supplied without a promise of uninterrupted or error-free operation, subject to rights that cannot lawfully be excluded.</p><h2>Account security</h2><p>Keep your recovery key private. It is the credential that restores your account. We store only its hash and cannot show the original again. Sign out on shared devices. Contact the operator about suspected unauthorised access without sending the key itself.</p><h2>Ownership and contact</h2><p>You retain your rights in your input. Processing your text for a requested translation does not transfer ownership of it to us. Browser providers and payment processors supply their own services under their terms. Contact details and seller information are linked in the footer.</p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}, "/tools/subtitle-maker": {"content": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Subtitle draft maker · PhraseLane</title><meta name=\"description\" content=\"Create a local SRT draft from one caption per line. No audio upload or automatic transcription.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Subtitle draft maker\"><meta property=\"og:description\" content=\"Create a local SRT draft from one caption per line. No audio upload or automatic transcription.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/tools/subtitle-maker\"><link rel=\"canonical\" href=\"https://phrase-lane-billing-sandbox.fmfm-stars.workers.dev/tools/subtitle-maker\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"><script src=\"/app.js\" defer></script></head><body><aside role=\"note\" style=\"padding:12px;background:#fff2c5;color:#342e1b\">Sandbox verification only. Billing is disabled. No live payment is accepted.</aside><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"wrap\"><header class=\"hero\"><div><span class=\"eyebrow\">A small creator tool</span><h1>Words with<br><em>a little timing.</em></h1></div><p>One caption per line. An SRT draft in one click. Everything in this tool is formatted in your browser.</p></header><section class=\"workspace\"><div class=\"workhead\"><div class=\"tabs\"><a href=\"/#workspace\">Text & voice</a><a class=\"active\" href=\"/tools/subtitle-maker\">Subtitle maker</a></div><span class=\"badge\">LOCAL TOOL</span></div><div class=\"panels\"><div class=\"pane\"><label for=\"captions\">Captions, one per line</label><textarea id=\"captions\" maxlength=\"20000\" placeholder=\"Welcome to our studio.&#10;Today we are sharing a new idea.\"></textarea><label for=\"duration\">Seconds per caption</label> <select id=\"duration\"><option value=\"2\">2 seconds</option><option value=\"3\" selected>3 seconds</option><option value=\"4\">4 seconds</option><option value=\"5\">5 seconds</option></select></div><div class=\"pane\"><label for=\"srtOutput\">Your SRT draft</label><textarea id=\"srtOutput\" readonly placeholder=\"Caption numbers and timestamps appear here.\"></textarea><button id=\"saveSrt\" class=\"iconbtn\">Download .srt</button></div></div><div class=\"workfoot\"><div id=\"status\" class=\"status\" role=\"status\">Even timing is a starting point. Adjust it to match your video.</div><div class=\"row\"><button id=\"clearSrt\" class=\"iconbtn\">Clear</button><button id=\"makeSrt\" class=\"button\">Create captions ↗</button></div></div></section><p class=\"micro\">Up to 200 captions. No audio processing, automatic transcription or translation is performed by this tool.</p><p><a href=\"/blog/subtitle-draft\">Read the subtitle workflow →</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>\n", "type": "text/html; charset=utf-8"}};
const encoder = new TextEncoder();
export const LANGUAGES = {en:'English',es:'Spanish',fr:'French',de:'German',it:'Italian',pt:'Portuguese',ja:'Japanese',ko:'Korean',zh:'Chinese',ar:'Arabic',hi:'Hindi',nl:'Dutch'};
const now = () => Math.floor(Date.now()/1000);
const hex = b => [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');
export const digest = async s => hex(await crypto.subtle.digest('SHA-256',encoder.encode(s)));
const token = () => hex(crypto.getRandomValues(new Uint8Array(32)));
class HttpError extends Error {constructor(status,message){super(message);this.status=status;}}
const fail = (s,m) => {throw new HttpError(s,m);};
export function secureHeaders(contentType='application/json; charset=utf-8') {return {'Content-Type':contentType,'Cache-Control':'no-store','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; media-src 'self' blob:; object-src 'none'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'",'Strict-Transport-Security':'max-age=31536000','X-Content-Type-Options':'nosniff','X-Frame-Options':'DENY','Referrer-Policy':'no-referrer','Permissions-Policy':'microphone=(self), camera=(), geolocation=(), payment=()'};}
const json=(value,status=200,extra={})=>new Response(JSON.stringify(value),{status,headers:{...secureHeaders(),...extra}});
const cookie = (t,age=2592000) => `__Host-phrase_session=${t}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${age}`;
export function sameOrigin(r) {if(r.headers.get('Origin')!==new URL(r.url).origin)fail(403,'Please use this website to make this request.');}
export async function readLimited(r,max=10000){if(Number(r.headers.get('Content-Length')||0)>max)fail(413,'Request is too large.');if(!r.body)return '';const reader=r.body.getReader();let n=0,parts=[];try{while(true){const {done,value}=await reader.read();if(done)break;n+=value.byteLength;if(n>max){await reader.cancel();fail(413,'Request is too large.');}parts.push(value);}}finally{reader.releaseLock();}const bytes=new Uint8Array(n);let p=0;for(const a of parts){bytes.set(a,p);p+=a.length;}return new TextDecoder().decode(bytes);}
async function body(r){if(!(r.headers.get('Content-Type')||'').startsWith('application/json'))fail(415,'Send JSON.');try{return JSON.parse(await readLimited(r));}catch(e){if(e instanceof HttpError)throw e;fail(400,'Invalid JSON.');}}
export function validateTranslation(b,max=500){if(!b||typeof b.text!=='string'||!b.text.trim())fail(400,'Enter text to translate.');const text=b.text.trim();if([...text].length>max)fail(400,`Use ${max} characters or fewer.`);if(!Object.hasOwn(LANGUAGES,b.source)||!Object.hasOwn(LANGUAGES,b.target))fail(400,'Choose a supported language.');return {text,source_lang:b.source,target_lang:b.target};}
async function consume(env,key,amount,limit,expires){if(!Number.isFinite(limit)||limit<amount||amount<1)fail(429,'Usage limit reached.');const row=await env.DB.prepare('INSERT INTO usage(key,amount,expires) VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET amount=usage.amount+excluded.amount WHERE usage.amount+excluded.amount<=? RETURNING amount').bind(key,amount,expires,limit).first();if(!row)fail(429,'Usage limit reached. Please try again after the allowance resets.');return row.amount;}
async function network(r,env){if(!env.QUOTA_SALT||!env.DB)fail(503,'The service is being configured. Please try later.');return digest(`${env.QUOTA_SALT}:${r.headers.get('CF-Connecting-IP')||'unknown'}`);}
async function throttle(r,env,kind,limit=20,period=60){const key=await network(r,env);const bucket=Math.floor(now()/period);await consume(env,`rate:${kind}:${key}:${bucket}`,1,limit,(bucket+2)*period);return key;}
async function current(r,env){const c=r.headers.get('Cookie')||'';const raw=c.match(/(?:^|;\s*)__Host-phrase_session=([a-f0-9]{64})(?:;|$)/)?.[1];if(!raw||!env.DB)return null;return env.DB.prepare('SELECT a.* FROM accounts a JOIN sessions s ON s.account_id=a.id WHERE s.hash=? AND s.expires>?').bind(await digest(raw),now()).first();}
async function required(r,env){const a=await current(r,env);if(!a)fail(401,'Create or restore your account first.');return a;}
async function session(env,id){const t=token();await env.DB.prepare('INSERT INTO sessions(hash,account_id,expires) VALUES(?,?,?)').bind(await digest(t),id,now()+2592000).run();return t;}
const isPro=a=>a&&['active','trialing'].includes(a.status)&&a.valid_until>now();
const billingEnvironment=e=>['live','test'].includes(e.BILLING_MODE)&&new RegExp('^(?:sk|rk)_'+e.BILLING_MODE+'_').test(e.STRIPE_SECRET_KEY||'');
export function billingReady(e){return e.BILLING_ENABLED==='true'&&e.LEGAL_READY==='true'&&e.BILLING_TESTED==='true'&&billingEnvironment(e)&&!!e.STRIPE_SECRET_KEY&&!!e.STRIPE_WEBHOOK_SECRET&&!!e.STRIPE_PRICE_ID&&!!e.SELLER_NAME&&!!e.SELLER_ADDRESS&&!!e.SELLER_PHONE&&!!e.CONTACT_EMAIL;}
async function stripe(env,path,data=null,idempotency=null){if(!billingEnvironment(env))fail(503,'Subscriptions are not open yet.');const headers={Authorization:`Bearer ${env.STRIPE_SECRET_KEY}`,'Stripe-Version':'2026-08-26.dahlia'};if(data)headers['Content-Type']='application/x-www-form-urlencoded';if(idempotency)headers['Idempotency-Key']=idempotency;const res=await fetch(`https://api.stripe.com/v1/${path}`,{method:data?'POST':'GET',headers,body:data?new URLSearchParams(data):undefined,signal:AbortSignal.timeout(15000)});let out;try{out=await res.json();}catch{fail(502,'Billing service is temporarily unavailable.');}if(!res.ok)fail(502,'Billing service is temporarily unavailable.');return out;}
export async function verifyStripe(raw,header,secret,time=now()){if(!secret||!header)return false;const values=header.split(',').map(x=>x.split('='));const t=values.find(x=>x[0]==='t')?.[1];if(!/^\d+$/.test(t||'')||Math.abs(time-Number(t))>300)return false;const key=await crypto.subtle.importKey('raw',encoder.encode(secret),{name:'HMAC',hash:'SHA-256'},false,['verify']);for(const [k,v] of values){if(k!=='v1'||!/^([a-f0-9]{2}){32}$/.test(v))continue;const sig=Uint8Array.from(v.match(/../g),x=>parseInt(x,16));if(await crypto.subtle.verify('HMAC',key,sig,encoder.encode(`${t}.${raw}`)))return true;}return false;}
async function syncSub(env,id,accountId,eventId=null){const s=await stripe(env,`subscriptions/${encodeURIComponent(id)}`);if(s.id!==id||s.livemode!==(env.BILLING_MODE==='live'))fail(403,'Subscription environment does not match.');accountId=accountId||s.metadata?.account_id;if(!accountId||!await env.DB.prepare('SELECT id FROM accounts WHERE id=?').bind(accountId).first())fail(503,'Subscription account is not available yet.');if(s.metadata?.account_id!==accountId)fail(403,'Subscription does not match this account.');if(!s.items?.data?.some(i=>i.price?.id===env.STRIPE_PRICE_ID))fail(403,'Subscription price does not match.');const end=Math.max(s.current_period_end||0,...s.items.data.map(i=>i.current_period_end||0));const update=env.DB.prepare('UPDATE accounts SET customer=?,subscription=?,status=?,valid_until=? WHERE id=?').bind(typeof s.customer==='string'?s.customer:s.customer.id,s.id,s.status,end,accountId);if(eventId)await env.DB.batch([update,env.DB.prepare('INSERT OR IGNORE INTO stripe_events(id,processed) VALUES(?,?)').bind(eventId,now())]);else await update.run();return s;}
async function webhook(r,env){
 const raw=await readLimited(r,262144);
 if(!await verifyStripe(raw,r.headers.get('stripe-signature'),env.STRIPE_WEBHOOK_SECRET))fail(400,'Invalid webhook signature.');
 let e;try{e=JSON.parse(raw);}catch{fail(400,'Invalid event.');}
 if(!e||typeof e.id!=='string'||!/^evt_[a-zA-Z0-9_]+$/.test(e.id)||typeof e.type!=='string')fail(400,'Invalid event.');
 const expectedLive=env.BILLING_MODE==='live';
 if(!['live','test'].includes(env.BILLING_MODE)||e.livemode!==expectedLive)fail(400,'Incorrect billing environment.');
 const checkoutEvents=['checkout.session.completed','checkout.session.async_payment_succeeded'];
 const subscriptionEvents=['customer.subscription.created','customer.subscription.updated','customer.subscription.deleted'];
 const invoiceEvents=['invoice.paid','invoice.payment_failed','invoice.payment_action_required'];
 if(![...checkoutEvents,...subscriptionEvents,...invoiceEvents].includes(e.type))return json({received:true});
 if(await env.DB.prepare('SELECT id FROM stripe_events WHERE id=?').bind(e.id).first())return json({received:true});
 const obj=e.data?.object;if(!obj||typeof obj!=='object')fail(400,'Invalid event.');
 let subscription=null,accountId=null;
 const stringId=v=>typeof v==='string'?v:v?.id;
 if(checkoutEvents.includes(e.type)){
  if(obj.mode!=='subscription'||obj.payment_status!=='paid')return json({received:true});
  subscription=stringId(obj.subscription);accountId=obj.client_reference_id;
 }else if(subscriptionEvents.includes(e.type)){
  subscription=obj.id;accountId=obj.metadata?.account_id;
 }else{
  subscription=stringId(obj.parent?.subscription_details?.subscription||obj.subscription);
 }
 if(subscription){
  if(typeof subscription!=='string'||!/^sub_[a-zA-Z0-9_]+$/.test(subscription))fail(400,'Invalid subscription.');
  if(!accountId)accountId=(await env.DB.prepare('SELECT id FROM accounts WHERE subscription=?').bind(subscription).first())?.id;
  await syncSub(env,subscription,accountId,e.id);
  return json({received:true});
 }
 // Non-subscription invoices belong to other products. Never mark an
 // unresolved paid checkout or subscription notification as completed.
 if(!invoiceEvents.includes(e.type))fail(400,'Missing subscription reference.');
 return json({received:true});
}
export async function api(r,env,ctx){const u=new URL(r.url);const path=u.pathname;if(path==='/api/config'&&r.method==='GET')return json({billing:billingReady(env),languages:LANGUAGES,maxChars:500,freeRequests:10,proPrice:9});if(path==='/api/webhook'&&r.method==='POST')return webhook(r,env);if(path==='/api/account'&&r.method==='GET'){const a=await current(r,env);const month=new Date().toISOString().slice(0,7);let used=0;if(a)used=(await env.DB.prepare('SELECT amount FROM usage WHERE key=?').bind(`pro:${a.id}:${month}`).first())?.amount||0;return json({signedIn:!!a,plan:isPro(a)?'pro':'free',status:a?.status||'free',used,limit:50000,billing:billingReady(env),validUntil:a?.valid_until||0});}
if(r.method!=='POST')fail(405,'Method not allowed.');sameOrigin(r);
if(path==='/api/accounts'){await throttle(r,env,'signup',3,86400);await consume(env,`signup-global:${Math.floor(now()/86400)}`,1,100,now()+172800);const key=token(),id=crypto.randomUUID();await env.DB.prepare('INSERT INTO accounts(id,recovery_hash,created) VALUES(?,?,?)').bind(id,await digest(key),now()).run();return json({recoveryKey:`PL-${key}`},201,{'Set-Cookie':cookie(await session(env,id))});}
if(path==='/api/login'){await throttle(r,env,'login',10,3600);const b=await body(r);if(typeof b.key!=='string'||!/^PL-[a-f0-9]{64}$/.test(b.key))fail(401,'Account key not recognised.');const a=await env.DB.prepare('SELECT id FROM accounts WHERE recovery_hash=?').bind(await digest(b.key.slice(3))).first();if(!a)fail(401,'Account key not recognised.');return json({ok:true},200,{'Set-Cookie':cookie(await session(env,a.id))});}
if(path==='/api/logout'){const raw=(r.headers.get('Cookie')||'').match(/__Host-phrase_session=([a-f0-9]{64})/)?.[1];if(raw)await env.DB.prepare('DELETE FROM sessions WHERE hash=?').bind(await digest(raw)).run();return json({ok:true},200,{'Set-Cookie':cookie('',0)});}
if(path==='/api/translate'){const ip=await throttle(r,env,'translate',6,60);const a=await current(r,env),pro=isPro(a);const input=validateTranslation(await body(r),pro?1000:500);if(input.source_lang===input.target_lang)return json({text:input.text,elapsedMs:0,engine:'Same language'});const day=Math.floor(now()/86400);if(pro){await consume(env,`pro-day:${a.id}:${day}`,1,100,(day+2)*86400);await consume(env,`pro:${a.id}:${new Date().toISOString().slice(0,7)}`,[...input.text].length,50000,now()+5356800);}else await consume(env,`free:${ip}:${day}`,1,10,(day+2)*86400);
// Global cost fuse is independent of visitor identity; exceeding it fails closed.
await consume(env,`global:${day}`,1,Number(env.DAILY_TRANSLATION_CAP||200),(day+2)*86400);const start=Date.now();let output;try{output=await env.AI.run('@cf/meta/m2m100-1.2b',input);}catch{fail(503,'Translation is temporarily busy. Your draft is still here; try later.');}if(typeof output?.translated_text!=='string'||!output.translated_text.trim())fail(502,'No translation returned. Please try a shorter sentence.');return json({text:output.translated_text,elapsedMs:Date.now()-start,engine:'Cloudflare AI'});}
if(path==='/api/checkout'){await throttle(r,env,'checkout',5,3600);if(!billingReady(env))fail(503,'Pro subscriptions are not open yet. The free tools are available.');const a=await required(r,env);const b=await body(r);if(b.savedKey!==true||b.acceptedTerms!==true)fail(400,'Save your account key and accept the terms first.');if(isPro(a))fail(409,'You already have Pro. Use Manage billing.');const params={mode:'subscription',integration_identifier:'phrase-lane-pro-zqmbtvar','subscription_data[billing_mode][type]':'flexible','line_items[0][price]':env.STRIPE_PRICE_ID,'line_items[0][quantity]':'1',client_reference_id:a.id,'subscription_data[metadata][account_id]':a.id,success_url:`${u.origin}/account?checkout={CHECKOUT_SESSION_ID}`,cancel_url:`${u.origin}/pricing`,allow_promotion_codes:'false'};if(a.customer)params.customer=a.customer;const s=await stripe(env,'checkout/sessions',params,`checkout-${a.id}-${Math.floor(now()/3600)}`);return json({url:s.url});}
if(path==='/api/sync'){await throttle(r,env,'sync',10,60);const a=await required(r,env),b=await body(r);if(typeof b.checkout!=='string'||!/^cs_[a-zA-Z0-9_]{10,200}$/.test(b.checkout))fail(400,'Invalid checkout reference.');const s=await stripe(env,`checkout/sessions/${encodeURIComponent(b.checkout)}`);if(s.client_reference_id!==a.id||s.mode!=='subscription'||s.status!=='complete'||s.payment_status!=='paid'||!s.subscription)fail(403,'Payment is not confirmed for this account.');await syncSub(env,typeof s.subscription==='string'?s.subscription:s.subscription.id,a.id);return json({ok:true});}
if(path==='/api/portal'){await throttle(r,env,'portal',6,60);const a=await required(r,env);if(!a.customer)fail(409,'There is no billing account yet.');const p=await stripe(env,'billing_portal/sessions',{customer:a.customer,return_url:`${u.origin}/account`});return json({url:p.url});}
fail(404,'Not found.');}
export default {async fetch(r,env,ctx){try{const url=new URL(r.url);if(url.pathname.startsWith('/api/'))return await api(r,env,ctx);if(!['GET','HEAD'].includes(r.method))fail(405,'Method not allowed.');let path=url.pathname.replace(/\/$/,'')||'/';if(path==='/robots.txt')return new Response(`User-agent: *\nAllow: /\nDisallow: /account\nDisallow: /api/\nSitemap: ${url.origin}/sitemap.xml`,{headers:secureHeaders('text/plain')});if(path==='/sitemap.xml'){const pages=Object.keys(ASSETS).filter(x=>ASSETS[x].type.startsWith('text/html')&&!['/account','/404'].includes(x));return new Response(`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${pages.map(p=>`<url><loc>${url.origin}${p}</loc></url>`).join('')}</urlset>`,{headers:secureHeaders('application/xml')});}
const asset=ASSETS[path]||ASSETS['/404'];let text=asset.content;if(path==='/legal'&&env.LEGAL_READY==='true'){const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));text=text.replace('<!--SELLER-->',`<dl><dt>Seller</dt><dd>${esc(env.SELLER_NAME)}</dd><dt>Business address</dt><dd>${esc(env.SELLER_ADDRESS)}</dd><dt>Telephone</dt><dd>${esc(env.SELLER_PHONE)}</dd><dt>Contact</dt><dd>${esc(env.CONTACT_EMAIL)}</dd></dl>`);}return new Response(r.method==='HEAD'?null:text,{status:ASSETS[path]?200:404,headers:{...secureHeaders(asset.type),'Cache-Control':path==='/legal'?'no-store':'public, max-age=300'}});}catch(e){return json({error:e instanceof HttpError?e.message:'Service temporarily unavailable. Please try again.',code:e instanceof HttpError?e.status:503},e instanceof HttpError?e.status:503);}},async scheduled(event,env){await env.DB.batch([env.DB.prepare('DELETE FROM usage WHERE expires<?').bind(now()),env.DB.prepare('DELETE FROM sessions WHERE expires<?').bind(now())]);}};


